{"cards": [{"node_code": "N_a3d8153d3fda6c27", "definition": "记录数控机床、计算机辅助设计（CAD）与制造（CAM）及柔性制造系统（FMS）从概念提出到工业普及的历史演变过程。", "boundary": "本节点聚焦于计算机技术直接介入机械物理加工与设计流程的历史。边界在于侧重“数字化对物理制造/设计环节的改造”，如G代码发展、CAD软件迭代及FMS架构演进。若内容侧重纯算法理论或无物理加工背景的纯软件历史，不在此列；若侧重企业级数据管理，归入PLM节点。", "includes": ["数控机床从点位控制到连续轨迹控制的技术演进史", "CAD/CAM软件从专用系统到通用平台的发展脉络", "柔性制造系统（FMS）及计算机集成制造（CIMS）的兴起与实施案例"], "excludes": ["纯计算机图形学算法或数据结构研究", "基于人工智能的自主决策制造系统（应归入智能制造相关节点）"], "sibling_distinctions": [{"other_code": "N_444c17c35521b135", "rule": "本节点侧重计算机对物理加工与设计流程的直接控制与执行（如数控、CAM）；兄弟节点侧重利用计算机进行虚拟分析、验证与建模（如仿真、数字样机）。"}, {"other_code": "N_d2c4d5c95fbaf205", "rule": "本节点侧重车间层面的生产执行与工艺数字化；兄弟节点侧重企业层面的数据管理、产品全生命周期信息及业务流程信息化。"}], "cross_boundary_rule": "若内容描述如何利用计算机指令控制机床或生成加工路径，归入本节点；若描述如何利用计算机模拟产品性能或管理产品数据，则分别归入仿真或PLM节点。"}, {"node_code": "N_444c17c35521b135", "definition": "记录计算力学、有限元分析（FEA）及数字样机（Virtual Prototyping）技术在机械工程设计验证中应用的发展历程。", "boundary": "本节点聚焦于“虚拟空间”中机械性能预测与验证技术的历史。边界在于侧重通过数值计算替代或辅助物理实验的过程，包括从早期手算到高性能计算集群的应用演变。若内容涉及实际物理样机的制造与测试，或纯数学算法推导，不作为主挂载。", "includes": ["有限元方法（FEM）在结构、热、流体分析中的普及历史", "多体动力学、碰撞仿真等专用工程仿真软件的发展脉络", "数字样机概念从单一部件仿真到系统级虚拟验证的演进"], "excludes": ["纯数学数值分析算法的理论推导", "物理实验测试技术与设备的历史（除非作为仿真验证的对比背景）"], "sibling_distinctions": [{"other_code": "N_a3d8153d3fda6c27", "rule": "本节点侧重设计阶段的虚拟分析与验证；兄弟节点侧重制造阶段的物理加工控制与设计数据生成。"}, {"other_code": "N_d2c4d5c95fbaf205", "rule": "本节点侧重仿真工具与方法论的技术演进；兄弟节点侧重仿真数据在企业信息流中的管理与集成。"}], "cross_boundary_rule": "若内容描述如何建立模型并计算力学/热学响应，归入本节点；若描述仿真结果如何被PLM系统存储或用于驱动数控加工，则根据侧重点归入PLM或数控节点。"}, {"node_code": "N_d2c4d5c95fbaf205", "definition": "记录企业资源计划（ERP）、产品生命周期管理（PLM）及数字化工厂建设在机械制造业中应用的历史进程。", "boundary": "本节点聚焦于机械工程企业“管理流程”与“数据流”的信息化历史。边界在于侧重商业软件、管理理念及系统集成对制造组织的影响，如从MRP到ERP的演变、PLM对研发数据的统一管理。若内容侧重具体车间设备控制，归入数控节点；若侧重纯IT基础设施，不作主挂载。", "includes": ["MRP、ERP系统在机械制造企业中的引入与实施历史", "PLM系统对产品设计、工艺、制造数据全生命周期管理的演进", "数字化工厂、智能工厂概念从理论到试点落地的历史案例"], "excludes": ["纯计算机科学中的数据库技术或网络协议研究", "具体机械零部件的加工工艺参数设定"], "sibling_distinctions": [{"other_code": "N_a3d8153d3fda6c27", "rule": "本节点侧重企业级数据管理与业务流程优化；兄弟节点侧重车间级生产执行与工艺数字化。"}, {"other_code": "N_444c17c35521b135", "rule": "本节点侧重仿真数据的管理与集成；兄弟节点侧重仿真技术本身的方法论与工具发展。"}], "cross_boundary_rule": "若内容描述软件如何管理产品数据或优化供应链，归入本节点；若描述软件如何控制机床或计算物理场，则归入数控或仿真节点。"}]}
